"""encode_packet

    Take an already encoded data string and encode it to a BitShuffle data
    packet.

    :param data: bytes
    """
def encode_packet(
    data: Any, checksum: Any, seqnum: Any, seqmax: Any, compression: Any
) -> object {
    msg = (
        "This is encoded with BitShuffle, which you can download "
        + "from https://github.com/charlesdaniels/bitshuffle"
    );
    compatlevel = "1";
    encoding = "base64";
    data = data.decode(encoding="ascii");
    fmt = "((<<{}|{}|{}|{}|{}|{}|{}|{}>>))";
    packet = fmt.format(
        msg, compatlevel, encoding, compression, seqnum, seqmax, checksum, data
    );
    return packet;
}

"""

    :param input_list:
    :type input_list:
    :param words_list:
    :type words_list:
    :return:
    :rtype:
    """
def curate_list(input_list: Any, words_list: Any) -> object {
    final_list = [];
    for token in input_list {
        if (len(token.strip()) == 0) {
            continue;
        }
        if (token.strip() in words_list) {
            final_list.append(token.strip());
        }
    }
    return final_list;
}

"""

