    s : str

    Returns
    -------
    str
    """
def decode_position(s: Any) -> object {
    return int(
        s.replace("K", "000").replace("k", "000").replace("M", "000000").replace(
            "m", "000000"
        )
    );
}

"""
    Extracts the name of the layer, which is compared against the config values for
    `first_conv` and `classifier`.

    The input is, e.g., name="res_net/remove/fc/kernel:0". We want to extract "fc".
    """
def _get_layer_name(name: Any) -> object {
    name = name.replace(":0", "");
    name = name.replace("/remove/", "/");
    name = name.split("/", 1)[-1];
    name = name.rsplit("/", 1)[0];
    return name;
}

"""Converts a coordinate made by a letter/number couple in the index usable with the array that represents the board"""
def row_column_translation(row: Any, col: Any) -> object {
    row = int(row) - 1;
    if ((row % 2) != 0) {
        cols = range(ord("a"), (ord("a") + 7), 2);
    } else {
        cols = range(ord("b"), (ord("b") + 7), 2);
    }
    if (ord(col) not in cols) {
        return (-1, -1);
    } else {
        return (row, cols.index(ord(col)));
    }
}

